"""Render completed R60 scorecard; does not run measurements or change Git."""
from pathlib import Path
import json,sys
s=json.loads(Path(sys.argv[1]).read_text());out=Path(sys.argv[2]);p=s['primary'];ref=p['reference_seconds'];before=p['medians']['before'];after=p['medians']['after'];comparison=p['comparisons']['after_over_before']
lines=['# R60: static vector address generation','',f"Candidate compiler: `{s['static']['after']['source']}`. Baseline R59 compiler: `{s['static']['before']['source']}`. Only GPU was rebuilt; every other production library hash, feature set and profile is unchanged.",'',f"The complete eight-byte level-12 call measured **{after['multiple_of_reference']:.6f}× the reference**, from **{before['multiple_of_reference']:.6f}×** in the matched baseline cohort. Candidate/baseline elapsed is **{comparison['pooled_ratio']:.8f}×** ({s['changes_percent']['primary_seconds']:+.4f}%). Reference median: {ref*1000:.6f} ms.",'','The source-level change uses direct linear addressing when the existing numeric proof establishes a unit row or column dimension; general rectangular geometry retains its normal mapping. This changes emitted arithmetic, not the compressor algorithm or its logical resource charges.','', '| Metric | Reference | R59 baseline | R60 candidate | Change |','|---|---:|---:|---:|---:|',f"| Primary elapsed (ms) | {ref*1000:.6f} | {before['seconds']*1000:.6f} | {after['seconds']*1000:.6f} | {s['changes_percent']['primary_seconds']:+.4f}% |"]
for section,key,label in [('cpu','instructions','Retired instructions'),('cpu','cycles','CPU cycles'),('allocation','allocation_requests','Allocation requests'),('allocation','requested_bytes','Requested bytes'),('allocation','reallocations','Reallocations'),('allocation','peak_live_usable','Peak allocator live usable bytes'),('allocation','incremental_peak_live_usable','Incremental peak live usable bytes'),('cpu','rss_after','RSS after call'),('cpu','physical_after','Physical footprint after call')]:
 values=[s[section][variant][key]['median'] for variant in ['reference','before','after']];change=s['changes_percent'][key];lines.append('| '+label+' | '+' | '.join(f'{v:,.1f}' if int(v)!=v else f'{v:,.0f}' for v in values)+' | '+('—' if change is None else f'{change:+.4f}%')+' |')
lines.insert(4, f"**Retired instructions improve, with adverse latency and binary-size tradeoffs:** elapsed increased {s['changes_percent']['primary_seconds']:.4f}%, cycles increased {s['changes_percent']['cycles']:.4f}%, while retired instructions decreased {-s['changes_percent']['instructions']:.4f}%. This is not an elapsed-time or binary-size win. The candidate is retained for the independent instruction objective; generated-code growth remains unresolved.")
lines.insert(5, '')
lines+=['','Primary elapsed, CPU counters, allocation counters and sampling are separate serialized cohorts. Their percentages are not multiplied or combined into a synthetic result. Requested bytes measure allocation requests, not initialized bytes copied. Allocator peak and post-call OS footprint are distinct measures; retained compiler/catalog/image storage is included.','', '## Matched pairs and contrary observations','', '| Pair | Baseline ms | Candidate ms | Candidate/baseline |','|---|---:|---:|---:|']
for group in p['groups']:lines.append(f"| {group['group']} | {group['medians']['before']*1000:.6f} | {group['medians']['after']*1000:.6f} | {group['after_over_before']:.8f}× |")
lines+=['',f"{comparison['improving_groups']}/4 independently prepared pairs and {comparison['improving_blocks']}/64 alternating blocks improve. Each pair has 16 blocks ×31 measured calls per variant: 3,968 total primary observations. Individual blocks within a prepared pair are descriptive, not independent experiments.",'', 'Counter directions that increased are retained below; an empty object means no listed median increased:','', '```json',json.dumps(s['contrary_counter_directions'],indent=2),'```','', '## Generated binary','', '| Metric | R59 baseline | R60 candidate |','|---|---:|---:|']
for key,label in [('code_bytes','Generated text bytes'),('stack_bytes','Machine entry stack bytes'),('typed_ir_version','Typed IR version'),('abi_version','ABI version')]:lines.append(f"| {label} | {s['static']['before'][key]:,} | {s['static']['after'][key]:,} |")
lines+=['','| Static instruction class | R59 | R60 | Delta |','|---|---:|---:|---:|']
for key in ['UDIV','MSUB','static_instructions']:
 audit=s['binary_audit'][key];lines.append(f"| {key} | {audit['before']:,} | {audit['after']:,} | {audit['delta']:+,} |")
lines+=['',f"Text grows by {s['binary_audit']['code_bytes']['delta']:,} bytes ({100*s['binary_audit']['code_bytes']['delta']/s['binary_audit']['code_bytes']['before']:.4f}%) and entry stack by {s['binary_audit']['stack_bytes']['delta']:,} bytes. Opcode deltas include LDR {s['binary_audit']['opcode_delta']['ldr']:+,}, MOV {s['binary_audit']['opcode_delta']['mov']:+,}, and MOVK {s['binary_audit']['opcode_delta']['movk']:+,}. The actual Object hashes and full disassembly census are in [binary-audit.json](binary-audit.json). These are static counts; retired instructions are measured separately.",'','The candidate Object is independently bound to its corresponding image and libraries. Equality with the baseline Object is not an acceptance requirement.']
if 'binary_growth_explanation' in s:lines+=['',s['binary_growth_explanation']]
lines+=['','## Diagnostic profiles and allocation census','','| Sampling measure | Baseline | Candidate |','|---|---:|---:|']
profiles=s['profiles']['profiles']
lines.append(f"| Total exclusive sample weights | {profiles['baseline']['total_exclusive_weights']} | {profiles['candidate']['total_exclusive_weights']} |")
for key in ['frame actions','tail cleanup','projection accounting','thread-local lookup','memory move/copy']:
 b=profiles['baseline']['ancestry_unions'][key];a=profiles['candidate']['ancestry_unions'][key];lines.append(f"| {key} | {b['weights']} ({b['percent']:.3f}%) | {a['weights']} ({a['percent']:.3f}%) |")
lines+=['','These ancestry groups overlap. They are sampling weights, not retired-instruction attribution; host sample movements do not establish a host optimization when only GPU code generation changed.',f"The complete candidate census reconciles all {s['census']['requests']:,} requests, {s['census']['requested_bytes']:,} requested bytes and {s['census']['reallocations']:,} reallocations with the separate heap counters. No allocation reduction is claimed."]
lines+=['', '## Correctness and unchanged workload','', 'The input is eight bytes `abcdefgh`; exact raw output remains `[75,76,74,78,73,77,75,207,0,0]`, with independent inflation. Output capacity remains 13 and is cleared/reused. The tree contains 262,144 U16 entries, the cache 1,500,513 U32 words, search depth is 300 and nice length 258. Input aliases, finite admission/error order, previous publication on failure and recovery remain covered. Logical work is 60,260,219,686 and comparison work 47,612; neither is a hardware instruction count. Final managed bytes and nodes remain zero.','', 'The source and bytecode are unchanged:','','```json',json.dumps(s['source_pins'],indent=2),'```','', '## Qualification','',f"All required local checks passed: **{s['validation']['all_required_checks_pass']}**. Exact counts come from archived inventories and executed receipts. Batches overlap; they are not a sum of unique tests.",'', '| Receipt | Expected tests | Observed | Passed |','|---|---:|---:|---|']
for row in s['validation']['checks']:
 if row.get('inventory_only'):continue
 lines.append(f"| `{row['receipt']}` | {row.get('expected_tests','—')} | {row.get('observed_tests',row.get('cases','—'))} | {row['passed']} |")
lines+=['','Skipped coverage:']
for row in s['validation']['skipped_coverage']:lines.append('- '+row.get('test',row.get('coverage'))+': '+row['disposition'])
lines+=['','Preflight attempts (both preserved, neither contributed a timing sample):']
for row in s['preflight_attempts']:lines.append('- Exit '+str(row['exit'])+', observations '+str(row['observations'])+': '+row['reason'])
lines+=['','## Replay','', 'Run `python3 reconstruct.py /new/empty/output/path` from this evidence packet. It verifies every archived receipt version, overlays versions chronologically and reproduces scorecard, profile and validation JSON. No compiler, compressor executable or performance rerun is required.','', 'This is a small-input complete-compression result. It does not establish larger-input throughput or a standalone minimum memory footprint. The candidate is retained for reduced retired instructions despite its larger generated text and stack; the cause of this growth remains under investigation. Elapsed and cycle medians are adverse; allocation counts are unchanged. No R61 result is combined with this decision.','']
out.write_text('\n'.join(lines))
